{
  "name": "Output Parser Agent 2b",
  "nodes": [
    {
      "parameters": {
        "functionCode": "// Universal JSON Output Parser for Agent 2b (n8n Function Node)
// Handles text, markdown fences, arrays, and malformed AI outputs

function getLLMText(payload) {
  const fromChoices = payload?.choices?.[0]?.message?.content;
  return (
    payload?.text ??
    payload?.response ??
    payload?.data ??
    fromChoices ??
    (typeof payload === 'string' ? payload : JSON.stringify(payload))
  );
}

function stripCodeFences(s) {
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  return fence ? fence[1].trim() : s.trim();
}

function extractBalancedJSON(s) {
  let start = -1, depth = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (ch === '}') {
      if (depth > 0) depth--;
      if (depth === 0 && start !== -1) {
        return s.slice(start, i + 1);
      }
    }
  }
  return null;
}

function coerceObject(x) {
  if (Array.isArray(x) && x.length && typeof x[0] === 'object') return x[0];
  if (x && typeof x === 'object') return x;
  return null;
}

const rawPayload = $json;
const rawText = getLLMText(rawPayload);
const text = stripCodeFences(String(rawText || ''));

let parsed = null;

// Attempt direct parse
try { parsed = JSON.parse(text); } catch {}

// Try balanced braces if direct parse failed
if (!parsed) {
  const candidate = extractBalancedJSON(text);
  if (candidate) { try { parsed = JSON.parse(candidate); } catch {} }
}

// Try last braces slice fallback
if (!parsed) {
  const lastBraces = text.lastIndexOf('}');
  const firstBrace = text.indexOf('{');
  if (firstBrace !== -1 && lastBraces !== -1 && lastBraces > firstBrace) {
    const slice = text.slice(firstBrace, lastBraces + 1);
    try { parsed = JSON.parse(slice); } catch {}
  }
}

parsed = coerceObject(parsed);

// Fallback if parsing fails
if (!parsed) {
  return [{ json: { error: 'JSON parsing failed (Agent 2b)', raw_preview: text.slice(0, 400) } }];
}

// Enforce expected schema
const schema = {
  prestataire_id: null,
  prestataire_label: null,
  categorie_id: null,
  categorie_label: null
};

for (const key in schema) {
  if (!(key in parsed)) parsed[key] = schema[key];
}

return [{ json: parsed }];"
